//! `zombie`: the Ep4 (Bayou) / Ep6 (Sherman Tech) zombies. One shared C source (`Monster_Base.c`,
//! `Zombie_Base.c`, `ZombieEpisodeFour.c` / `ZombieEpisodeSix.c`) compiled with a per-level file
//! (`ZombieLevel<N>.c`) into one module per level pack.
//! Port of `Game Logic Modules/Ep4_Bayou/Characters/Zombie/..` and `Ep6_ShermanTech/Characters/ZOMBIE/..`.
//! Reference build: zombieleveltwoa. The 11 builds are listed in `tools/rustport/zombie_family.txt`;
//! per-build literals and code shapes are in [`builds`] (generated by tools/rustport/gen_builds.py),
//! the initialised tables in [`maps`] (tools/rustport/gen_data_tables.py).
//!
//! This is a monster side of the Tome of Doom: a zombie sleeps / waits / wanders, chases and attacks
//! the leader hero; while the book is open it is scared and backs away; hooked by the beam
//! (0xd6/0x65) it struggles, is pulled in (0xd6/0x67) and captured (0xd6/0x68 ->
//! `Monster_BaseST_CAPTURED`).
//!
//! Module globals are shared by every instance (the engine swaps `pLocalData*` per instance), as on
//! the PS2. `pLocalDataMonster_Base` and `pLocalDatazombie_base` both point at the instance's one
//! local data block (GetLocalData grows and shares it), likewise the two global data pointers.
#![allow(non_snake_case, non_upper_case_globals, unused_variables, unused_mut, unused_assignments)]
#![allow(clippy::all)]

pub mod builds;
pub mod maps;

mod level;
mod monster_base;
mod zombie_base;
mod zombie_base_particle;

pub use level::*;
pub use monster_base::*;
pub use zombie_base::*;
pub use zombie_base_particle::*;

use crate::engine::{Engine, Mem, Ptr};
use crate::logic::ModuleDef;

pub static MODULE: ModuleDef = ModuleDef {
    name: "zombie",
    data_size: DATA_SIZE,
    ctor: zombie_levelConstructor,
    dtor: zombie_levelDestructor,
    register: None,
    // the initialised data the code reads (goCustomDataZombie, TmpMonsterMap) is written per build
    // by zombie_build_init; string literals are interned with `e.cstr`.
    init: &[],
    build_init: Some(zombie_build_init),
};

/// Index of a build in [`builds::BUILDS`] by its directory name.
pub fn build_index(sha8: &str) -> Option<usize> {
    builds::BUILDS.iter().position(|b| b.sha8 == sha8)
}

fn zombie_build_init(m: &mut Mem, data: Ptr, build: usize) {
    for (i, &w) in maps::GO_CUSTOM_DATA_ZOMBIE[build].iter().enumerate() {
        m.w32(data + (goCustomDataZombie - 0x10000) + i as u32 * 4, w);
    }
    for (i, &w) in maps::TMP_MONSTER_MAP[build].iter().enumerate() {
        m.w32(data + (TmpMonsterMap - 0x10000) + i as u32 * 4, w);
    }
}

// ---- module globals ----
// The builds place their globals at different addresses (the two tables have per-level sizes, and
// Ghidra left TmpMonsterMap unnamed in 5 builds); the image is private to the module, so the port uses
// one layout for every build: the tables at their largest size, then the pointers in _globals.h order.
/// per-zombie data: records {object id, monster type (L+0x44), ?, kill mask (L+0x40)} of 0x10 bytes;
/// 160 bytes max
pub const goCustomDataZombie: u32 = 0x10000;
/// per-monster-type data: records of 0x3c bytes {type, speeds and ranges...}; 240 bytes max
pub const TmpMonsterMap: u32 = 0x100a0;
pub const pAnimMngr: u32 = 0x10190;
pub const pFunction: u32 = 0x10194;
pub const pMiscFunc: u32 = 0x10198;
pub const pDebug: u32 = 0x1019c;
pub const pAnim: u32 = 0x101a0;
pub const pGameObj: u32 = 0x101a4;
pub const pPhysic: u32 = 0x101a8;
pub const pExtra: u32 = 0x101ac;
pub const pParticle: u32 = 0x101b0;
pub const pMath: u32 = 0x101b4;
pub const pStdlib: u32 = 0x101b8;
pub const pSound: u32 = 0x101bc;
pub const pSectorClip: u32 = 0x101c0;
pub const pLocalDataMonster_Base: u32 = 0x101c4;
pub const pGlobalDataMonster_Base: u32 = 0x101c8;
pub const pLocalDatazombie_base: u32 = 0x101cc;
pub const pGlobalDatazombie_base: u32 = 0x101d0;
pub const DATA_SIZE: u32 = 0x1d4;

/// `ALL` joint / bone selector (0x7fffffff)
pub(crate) const ALL: u32 = 0x7fff_ffff;

/// Address of a module global.
#[inline]
pub(crate) fn G(e: &Engine, a: u32) -> Ptr {
    e.rt.cur_data() + (a - 0x10000)
}
/// Current value of `pLocalDatazombie_base` (this instance's local data).
#[inline]
pub(crate) fn L(e: &Engine) -> Ptr {
    e.r32(G(e, pLocalDatazombie_base))
}
/// Current value of `pLocalDataMonster_Base` (the same block as [`L`] once both are registered).
#[inline]
pub(crate) fn LM(e: &Engine) -> Ptr {
    e.r32(G(e, pLocalDataMonster_Base))
}
/// Current value of `pGlobalDataMonster_Base` (byte-addressed: +0 game buffer 0, +4 game buffer 2,
/// +8 game buffer 1 (monster_baseConstructor), +0xc 0, +0x10 / +0x14 the Gaz / Grumeaux particle types).
#[inline]
pub(crate) fn GDM(e: &Engine) -> Ptr {
    e.r32(G(e, pGlobalDataMonster_Base))
}
/// Current value of `pGlobalDatazombie_base` (the same block as [`GDM`]).
#[inline]
pub(crate) fn GDZ(e: &Engine) -> Ptr {
    e.r32(G(e, pGlobalDatazombie_base))
}
/// Per-build literal (see builds.rs).
#[inline]
pub(crate) fn k(e: &Engine, i: usize) -> u32 {
    builds::BUILDS[e.rt.cur_build()].k[i]
}
/// Per-build code shape group of a function (see builds.rs).
#[inline]
pub(crate) fn g(e: &Engine, i: usize) -> u8 {
    builds::BUILDS[e.rt.cur_build()].g[i]
}
/// The current build's directory name.
#[inline]
pub(crate) fn build_key(e: &Engine) -> &'static str {
    builds::BUILDS[e.rt.cur_build()].sha8
}

/// `if (pDebug != NULL) (*pDebug->PrintDebugInfo)("Zombie", msg);`
pub(crate) fn debug_info(e: &mut Engine, msg: &str) {
    if e.r32(G(e, pDebug)) != 0 {
        let n = e.cstr("Zombie");
        let m = e.cstr(msg);
        crate::engine::LIBdebug::PrintDebugInfo(e, n, m);
    }
}

/// `*a |= bits`
#[inline]
pub(crate) fn or32(e: &mut Engine, a: Ptr, bits: u32) {
    let v = e.r32(a);
    e.w32(a, v | bits);
}
